
/**
 * Generated by framework_parser.py for: Resolução ANAC nº 400/2016
 * This function injects a complete analysis panel into a target container.
 * @param {targetContainerId: string, getTranscriptText: function, onAnalyze: function} options
 * - targetContainerId: The ID of the DOM element where the panel's button should be injected.
 * - getTranscriptText: A function that returns the current transcript text to be analyzed.
 * - onAnalyze: A callback function that receives the full prompt package for AI processing.
 */
function injectAnacResolution400Panel(options) {
    const { targetContainerId, getTranscriptText, onAnalyze } = options;

    const uiText = {
        title: 'Resolução ANAC nº 400/2016 Analysis',
        description: 'Analyze the current transcript for specific violations of the Resolução ANAC nº 400/2016. You can edit the prompt below.',
        buttonText: 'Analyze with Resolução ANAC nº 400/2016',
        defaultPrompt: `Analyze the provided transcript and identify behaviors that represent specific violations of the Resolução ANAC nº 400/2016.

KEY SECTIONS FOR ANALYSIS:
- **Fare Transparency**: // Content for Fare Transparency not automatically extracted. Please add manual description based on Art\\.\\s*[45].
- **Cancellation Rights**: // Content for Cancellation Rights not automatically extracted. Please add manual description based on Art\\.\\s*(9|10|11).
- **Information Disclosure**: // Content for Information Disclosure not automatically extracted. Please add manual description based on Art\\.\\s*5.
- **Baggage Policies**: ; e
V - indicação das empresas aéreas que realizarão o transporte, caso o voo seja realizado total ou parcialmente em código
compartilhado. (Incluído pela Resolução nº 692, de 21.09.2022) (../2022/resolucao-692)
§ 1º Para os fins desta Resolução, considera-se processo de comercialização aquele realizado no território nacional ou por meio
eletrônico direcionado ao mercado brasileiro.
§ 2º É vedada qualquer cobrança por serviço ou produto opcional que não tenha sido solicitado ativamente pelo...
- **Schedule Changes by Carrier**: // Content for Schedule Changes by Carrier not automatically extracted. Please add manual description based on Art\\.\\s*12.
- **Optional Services Opt-in**: ) pelo consumidor no
processo de comercialização da passagem aérea.
Art. 5º No processo de comercialização da passagem aérea, a partir da escolha da origem, do destino, da data da viagem e antes de ser
efetuado o pagamento pelos seus serviços, o transportador deverá prestar as seguintes informações ao usuário:
I - valor total da passagem aérea a ser pago em moeda nacional, com discriminação de todos os itens previstos no art. 4º, § 1º, desta
Resolução;
II - regras de não apresentação para ...

FOR EACH POTENTIAL VIOLATION IDENTIFIED:
1. Quote the exact transcript excerpt (with timestamp and speaker).
2. Reference the specific principle, article or section of the framework that was violated.
3. Briefly analyze the nature and severity of the violation.

PROVIDE A FINAL SUMMARY: Does this pattern of behavior indicate that the responsible entity is systematically failing to comply with the Resolução ANAC nº 400/2016?`
    };

    const systemPrompt = 'You are a specialized legal and compliance analyst. Your task is to analyze dialogues strictly in the context of Resolução ANAC nº 400/2016, identifying specific violations with precise references. Your output must be structured, factual, and cited.';

    const container = document.getElementById(targetContainerId);
    if (!container) {
        console.error(`[Panel Injector] Target container with ID #${targetContainerId} not found.`);
        return;
    }

    // 1. Create the activation button
    const analysisButton = document.createElement('button');
    analysisButton.textContent = uiText.buttonText;
    analysisButton.className = 'btn btn-special-analysis'; // Add your own styling
    container.appendChild(analysisButton);

    // 2. Create the analysis panel (initially hidden)
    const panel = document.createElement('div');
    panel.className = 'analysis-panel'; // Style this class
    panel.style.display = 'none';
    panel.innerHTML = `
        <div class="panel-header">
            <h3>${uiText.title}</h3>
            <button class="close-btn">&times;</button>
        </div>
        <p>${uiText.description}</p>
        <textarea class="prompt-textarea">${uiText.defaultPrompt}</textarea>
        <button class="execute-analysis-btn">Run Analysis</button>
    `;
    document.body.appendChild(panel); // Append to body to act like a modal

    // 3. Add event listeners
    analysisButton.addEventListener('click', () => {
        panel.style.display = 'block';
    });

    panel.querySelector('.close-btn').addEventListener('click', () => {
        panel.style.display = 'none';
    });

    panel.querySelector('.execute-analysis-btn').addEventListener('click', () => {
        if (typeof onAnalyze !== 'function' || typeof getTranscriptText !== 'function') {
            alert('Analysis function not configured correctly.');
            return;
        }
        
        const userPrompt = panel.querySelector('.prompt-textarea').value;
        const transcriptText = getTranscriptText();

        // Package everything for the AI
        const analysisPackage = {
            system_prompt: systemPrompt,
            user_prompt: userPrompt,
            transcript: transcriptText,
            framework: 'Resolução ANAC nº 400/2016'
        };

        onAnalyze(analysisPackage);
        panel.style.display = 'none'; // Hide panel after starting analysis
    });

    console.log(`Panel for Resolução ANAC nº 400/2016 injected and ready.`);
}
